from opentelemetry import trace

from opentelemetry.sdk.resources import Resource

from opentelemetry.sdk.trace import TracerProvider

from opentelemetry.sdk.trace.export import (
    BatchSpanProcessor,
    ConsoleSpanExporter
)

resource = Resource.create({
    "service.name": "enterprise-rag",
    "service.version": "1.0.0"
})

provider = TracerProvider(
    resource=resource
)

provider.add_span_processor(
    BatchSpanProcessor(
        ConsoleSpanExporter()
    )
)

trace.set_tracer_provider(provider)

tracer = trace.get_tracer(
    "enterprise-rag.pipeline"
)

from opentelemetry.trace import Status, StatusCode

def answer_question(
    question,
    principal,
    retrieve,
    generate,
    validate
):

    with tracer.start_as_current_span(
        "rag.request"
    ) as root:

        root.set_attribute(
            "rag.pipeline.version",
            "v1"
        )

        try:

            with tracer.start_as_current_span(
                "rag.retrieval"
            ) as span:

                documents = retrieve(
                    question,
                    principal
                )

                span.set_attribute(
                    "rag.retrieval.count",
                    len(documents)
                )

            with tracer.start_as_current_span(
                "rag.generation"
            ):

                answer = generate(
                    question,
                    documents
                )

            with tracer.start_as_current_span(
                "rag.output_validation"
            ) as span:

                valid = validate(
                    answer,
                    documents,
                    principal
                )

                span.set_attribute(
                    "rag.output.valid",
                    bool(valid)
                )

            if not valid:

                root.set_attribute(
                    "rag.outcome",
                    "blocked"
                )

                return {
                    "status": "blocked",
                    "answer": None
                }

            root.set_attribute(
                "rag.outcome",
                "success"
            )

            return {
                "status": "success",
                "answer": answer
            }

        except Exception as exc:

            root.set_attribute(
                "error.type",
                type(exc).__name__
            )

            root.set_status(
                Status(StatusCode.ERROR)
            )

            raise

